/* A compact, print-optimized weekly report. The browser's print sheet creates the PDF locally. */
(function(root,factory){
  const api=factory(root);
  if(typeof module!=="undefined"&&module.exports)module.exports=api;
  root.REP_REPORT_CARD=api;
})(typeof window!=="undefined"?window:(typeof globalThis!=="undefined"?globalThis:this),function(root){
  const esc=value=>String(value??"").replace(/[&<>"']/g,char=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[char]));
  function payloadFor(input){
    if(input?.period&&Number.isFinite(input?.adherence))return input;
    return root.REP_PRODUCT_SUITE?.weeklySummary(input||{},undefined,root.REP_PERFORMANCE_INSIGHTS)||{period:{start:"—",end:"—"},planned:0,completed:0,adherence:0,prs:[],avgReadiness:null,readinessDays:0,rescheduled:0,nextAction:"Keep logging workouts and recovery to unlock a weekly recommendation.",workouts:[]};
  }
  function generateReportHtml(input,{privateView=false}={}){
    const report=payloadFor(input),generated=new Date().toLocaleDateString(undefined,{year:"numeric",month:"long",day:"numeric"}),workouts=report.workouts||[],prs=report.prs||[];
    return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Health OS weekly report</title><style>
      :root{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:#122018;background:#fff}*{box-sizing:border-box}body{max-width:850px;margin:auto;padding:28px;line-height:1.45}.actions{display:flex;gap:8px;margin-bottom:18px}.actions button{border:0;border-radius:9px;padding:10px 14px;font-weight:750;background:#15251b;color:#fff}.actions button+button{background:#e8eee9;color:#15251b}header{display:flex;justify-content:space-between;gap:20px;border-bottom:3px solid #15251b;padding-bottom:18px}h1{font-size:26px;margin:0}header p,.muted{color:#607066;margin:4px 0}.hero{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:20px 0}.metric,.card{border:1px solid #dce4de;border-radius:14px;padding:15px;background:#f7faf8;break-inside:avoid}.metric small,.card h2{display:block;color:#607066;font-size:11px;letter-spacing:.08em;text-transform:uppercase}.metric strong{display:block;font-size:25px;margin-top:5px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.card h2{margin:0 0 10px}.card.full{grid-column:1/-1}.action{border-left:5px solid #52a96a;background:#edf8f0}.rows{display:grid;gap:7px}.row{display:flex;justify-content:space-between;gap:16px;border-bottom:1px solid #dce4de;padding:6px 0}.row:last-child{border:0}.privacy{font-size:11px;color:#607066;margin-top:20px}@media(max-width:620px){.hero{grid-template-columns:1fr 1fr}.grid{grid-template-columns:1fr}.card.full{grid-column:auto}body{padding:18px}}@media print{body{padding:0}.actions{display:none}.metric,.card{background:#fff}}
    </style></head><body><div class="actions"><button id="reportPrint" type="button">Save as PDF / Print</button>${privateView?"":'<button id="reportClose" type="button">Close</button>'}</div><header><div><h1>Health OS · Weekly Report</h1><p>${esc(report.period.start)} – ${esc(report.period.end)}</p></div><p>${esc(generated)}</p></header><section class="hero"><div class="metric"><small>Workouts</small><strong>${report.completed}/${report.planned}</strong></div><div class="metric"><small>Adherence</small><strong>${report.adherence}%</strong></div><div class="metric"><small>Readiness</small><strong>${report.avgReadiness===null?"—":`${report.avgReadiness}%`}</strong><span class="muted">${report.readinessDays}/7 days</span></div><div class="metric"><small>Recent PRs</small><strong>${prs.length}</strong></div></section><section class="grid"><article class="card"><h2>Completed workouts</h2><div class="rows">${workouts.length?workouts.map(row=>`<div class="row"><span>${esc(row.date)}</span><strong>${esc(row.session)}</strong></div>`).join(""):"<p class=\"muted\">No completed workouts in this period.</p>"}</div></article><article class="card"><h2>Personal records</h2><div class="rows">${prs.length?prs.map(row=>`<div class="row"><span>${esc(row.exercise)}</span><strong>${esc(row.value)} ${esc(row.unit)}</strong></div>`).join(""):"<p class=\"muted\">No new PRs this week.</p>"}</div></article><article class="card full action"><h2>Next recommended action</h2><strong>${esc(report.nextAction)}</strong><p class="muted">${report.rescheduled?`${report.rescheduled} missed session${report.rescheduled===1?" was":"s were"} automatically moved to an available recovery day.`:"The plan did not need an automatic reschedule this week."}</p></article></section><p class="privacy">Generated locally by Health OS. Wellness and training information is observational and is not a diagnosis or medical instruction.${privateView?" This capability link expires seven days after creation; anyone with the complete link can view it.":""}</p></body></html>`;
  }
  function bindActions(doc,target=root){doc.querySelector("#reportPrint")?.addEventListener("click",()=>target.print());doc.querySelector("#reportClose")?.addEventListener("click",()=>target.close());}
  function openHtml(html){const win=root.open?.("","_blank");if(!win)throw Error("Allow pop-ups to open the weekly report.");win.document.open();win.document.write(html);win.document.close();bindActions(win.document,win);return win;}
  function openPrintableReport(state){return openHtml(generateReportHtml(state));}
  function openWeeklyPayload(payload,{privateView=false}={}){return openHtml(generateReportHtml(payload,{privateView}));}
  return Object.freeze({payloadFor,generateReportHtml,bindActions,openPrintableReport,openWeeklyPayload});
});
